16	/// Complete the given command, shell-agnostic
17	pub fn complete(
18	    cmd: &mut clap::Command,
19	    args: Vec<OsString>,
20	    arg_index: usize,
21	    current_dir: Option<&std::path::Path>,
22	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
23	    debug!("complete: args={args:?}, arg_index={arg_index:?}, current_dir={current_dir:?}");
24	    cmd.build();
25	
26	    let raw_args = clap_lex::RawArgs::new(args);
27	    let mut cursor = raw_args.cursor();
28	    let mut target_cursor = raw_args.cursor();
29	    raw_args.seek(
30	        &mut target_cursor,
31	        clap_lex::SeekFrom::Start(arg_index as u64),
32	    );
33	    // As we loop, `cursor` will always be pointing to the next item
34	    raw_args.next_os(&mut target_cursor);
35	    debug!("complete: target_cursor={target_cursor:?}");
36	
37	    // TODO: Multicall support
38	    if !cmd.is_no_binary_name_set() {
39	        raw_args.next_os(&mut cursor);
40	    }
41	
42	    let mut current_cmd = &*cmd;
43	    let mut pos_index = 1;
44	    let mut is_escaped = false;
45	    let mut next_state = ParseState::ValueDone;
46	    // Ids of options explicitly present in `args[..arg_index]`, used to hide
47	    // conflicting candidates. Only recognized option names are recorded;
48	    // values, positionals, `--`-escaped words, default values and env values
49	    // never are.
50	    let mut explicit_opts = HashSet::<Id>::new();
51	    while let Some(arg) = raw_args.next(&mut cursor) {
52	        let current_state = next_state;
53	        next_state = ParseState::ValueDone;
54	        debug!(
55	            "complete::next: arg={:?}, current_state={current_state:?}, cursor={cursor:?}",
56	            arg.to_value_os(),
57	        );
58	        if cursor == target_cursor {
59	            let disabled = gather_disabled_args(current_cmd, &explicit_opts);
60	            return complete_arg(
61	                &arg,
62	                current_cmd,
63	                current_dir,
64	                pos_index,
65	                is_escaped,
66	                current_state,
67	                &disabled,
68	            );
69	        }
70	
71	        if let Ok(value) = arg.to_value() {
72	            if let Some(next_cmd) = current_cmd.find_subcommand(value) {
73	                current_cmd = next_cmd;
74	                pos_index = 1;
75	                continue;
76	            }
77	        }
78	
79	        if is_escaped {
80	            (next_state, pos_index) =
81	                parse_positional(current_cmd, pos_index, is_escaped, current_state);
82	        } else if arg.is_escape() {
83	            is_escaped = true;
84	        } else if opt_allows_hyphen(&current_state, &arg) {
85	            match current_state {
86	                ParseState::Opt((opt, count)) => next_state = parse_opt_value(opt, count),
87	                _ => unreachable!("else branch is only reachable in Opt state"),
88	            }
89	        } else if let Some((flag, value)) = arg.to_long() {
90	            if let Ok(flag) = flag {
91	                let opt = current_cmd.get_arguments().find(|a| {
92	                    let longs = a.get_long_and_visible_aliases();
93	                    let is_find = longs.map(|v| {
94	                        let mut iter = v.into_iter();
95	                        let s = iter.find(|s| *s == flag);
96	                        s.is_some()
97	                    });
98	                    is_find.unwrap_or(false)
99	                });
100	
101	                if let Some(opt) = opt {
102	                    explicit_opts.insert(opt.get_id().clone());
103	                    if opt.get_num_args().expect("built").takes_values() && value.is_none() {
104	                        next_state = ParseState::Opt((opt, 1));
105	                    };
106	                } else if pos_allows_hyphen(current_cmd, pos_index) {
107	                    (next_state, pos_index) =
108	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
109	                }
110	            }
111	        } else if let Some(short) = arg.to_short() {
112	            let (leading_flags, takes_value_opt, mut short) = parse_shortflags(current_cmd, short);
113	            // Every recognized flag in the cluster was explicitly supplied.
114	            for flag in leading_flags.chars() {
115	                if let Some(opt) = current_cmd.get_arguments().find(|a| {
116	                    a.get_short_and_visible_aliases()
117	                        .is_some_and(|shorts| shorts.contains(&flag))
118	                }) {
119	                    explicit_opts.insert(opt.get_id().clone());
120	                }
121	            }
122	            if let Some(opt) = takes_value_opt {
123	                if short.next_value_os().is_none() {
124	                    next_state = ParseState::Opt((opt, 1));
125	                }
126	            } else if pos_allows_hyphen(current_cmd, pos_index) {
127	                (next_state, pos_index) =
128	                    parse_positional(current_cmd, pos_index, is_escaped, current_state);
129	            }
130	        } else {
131	            match current_state {
132	                ParseState::ValueDone | ParseState::Pos(..) => {
133	                    (next_state, pos_index) =
134	                        parse_positional(current_cmd, pos_index, is_escaped, current_state);
135	                }
136	                ParseState::Opt((opt, count)) => next_state = parse_opt_value(opt, count),
137	            }
138	        }
139	    }
140	
141	    Err(std::io::Error::other("no completion generated"))
142	}
