156	fn complete_arg(
157	    arg: &clap_lex::ParsedArg<'_>,
158	    cmd: &clap::Command,
159	    current_dir: Option<&std::path::Path>,
160	    pos_index: usize,
161	    is_escaped: bool,
162	    state: ParseState<'_>,
163	    disabled: &HashSet<Id>,
164	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
165	    debug!(
166	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
167	        arg,
168	        cmd.get_name(),
169	        current_dir,
170	        pos_index,
171	        state
172	    );
173	    let mut completions = Vec::<CompletionCandidate>::new();
174	
175	    match state {
176	        ParseState::ValueDone => {
177	            // After `--`, only positional arguments are completed.
178	            if !is_escaped {
179	                if let Ok(value) = arg.to_value() {
180	                    completions.extend(complete_subcommand(value, cmd));
181	                }
182	            }
183	
184	            if let Some(positional) = cmd
185	                .get_positionals()
186	                .find(|p| p.get_index() == Some(pos_index))
187	            {
188	                if !disabled.contains(positional.get_id()) {
189	                    completions.extend(complete_arg_value(
190	                        arg.to_value(),
191	                        positional,
192	                        current_dir,
193	                        0,
194	                    ));
195	                }
196	            }
197	            if !is_escaped {
198	                completions.extend(complete_option(arg, cmd, current_dir, disabled));
199	            }
200	        }
201	        ParseState::Pos((_, num_arg)) => {
202	            if let Some(positional) = cmd
203	                .get_positionals()
204	                .find(|p| p.get_index() == Some(pos_index))
205	            {
206	                if !disabled.contains(positional.get_id()) {
207	                    completions.extend(complete_arg_value(
208	                        arg.to_value(),
209	                        positional,
210	                        current_dir,
211	                        num_arg.saturating_sub(1),
212	                    ));
213	                }
214	                if !is_escaped
215	                    && positional
216	                        .get_num_args()
217	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
218	                {
219	                    completions.extend(complete_option(arg, cmd, current_dir, disabled));
220	                }
221	            }
222	        }
223	        ParseState::Opt((opt, count)) => {
224	            if !disabled.contains(opt.get_id()) {
225	                completions.extend(complete_arg_value(
226	                    arg.to_value(),
227	                    opt,
228	                    current_dir,
229	                    count.saturating_sub(1),
230	                ));
231	            }
232	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
233	            if count > min {
234	                // Also complete this raw_arg as a positional argument, flags, options and subcommand.
235	                completions.extend(complete_arg(
236	                    arg,
237	                    cmd,
238	                    current_dir,
239	                    pos_index,
240	                    is_escaped,
241	                    ParseState::ValueDone,
242	                    disabled,
243	                )?);
244	            }
245	        }
246	    }
247	    if completions.iter().any(|a| !a.is_hide_set()) {
248	        completions.retain(|a| !a.is_hide_set());
249	    }
250	    let mut seen_ids = HashSet::new();
251	    completions.retain(move |a| {
252	        if let Some(id) = a.get_id().cloned() {
253	            seen_ids.insert(id)
254	        } else {
255	            true
256	        }
257	    });
258	
259	    let mut tags = Vec::new();
260	    for candidate in &completions {
261	        let tag = candidate.get_tag().cloned();
262	        if !tags.contains(&tag) {
263	            tags.push(tag);
264	        }
265	    }
266	    completions.sort_by_key(|c| {
267	        (
268	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
269	            c.get_display_order(),
270	        )
271	    });
272	
273	    Ok(completions)
274	}
