276	fn complete_option(
277	    arg: &clap_lex::ParsedArg<'_>,
278	    cmd: &clap::Command,
279	    current_dir: Option<&std::path::Path>,
280	    disabled: &HashSet<Id>,
281	) -> Vec<CompletionCandidate> {
282	    debug!("complete_option: arg={arg:?}, current_dir={current_dir:?}");
283	    let mut completions = Vec::<CompletionCandidate>::new();
284	    if arg.is_empty() {
285	        completions.extend(longs_and_visible_aliases(cmd, disabled));
286	        completions.extend(hidden_longs_aliases(cmd, disabled));
287	
288	        let dash_or_arg = if arg.is_empty() {
289	            "-".into()
290	        } else {
291	            arg.to_value_os().to_string_lossy()
292	        };
293	        completions.extend(
294	            shorts_and_visible_aliases(cmd, disabled)
295	                .into_iter()
296	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
297	        );
298	    } else if arg.is_stdio() {
299	        // HACK: Assuming knowledge of is_stdio
300	        let dash_or_arg = if arg.is_empty() {
301	            "-".into()
302	        } else {
303	            arg.to_value_os().to_string_lossy()
304	        };
305	        completions.extend(
306	            shorts_and_visible_aliases(cmd, disabled)
307	                .into_iter()
308	                .map(|comp| comp.add_prefix(dash_or_arg.to_string())),
309	        );
310	
311	        completions.extend(longs_and_visible_aliases(cmd, disabled));
312	        completions.extend(hidden_longs_aliases(cmd, disabled));
313	    } else if arg.is_escape() {
314	        // HACK: Assuming knowledge of is_escape
315	        completions.extend(longs_and_visible_aliases(cmd, disabled));
316	        completions.extend(hidden_longs_aliases(cmd, disabled));
317	    } else if let Some((flag, value)) = arg.to_long() {
318	        if let Ok(flag) = flag {
319	            if let Some(value) = value {
320	                if let Some(arg) = cmd.get_arguments().find(|a| a.get_long() == Some(flag)) {
321	                    if !disabled.contains(arg.get_id()) {
322	                        completions.extend(
323	                            complete_arg_value(value.to_str().ok_or(value), arg, current_dir, 0)
324	                                .into_iter()
325	                                .map(|comp| comp.add_prefix(format!("--{flag}="))),
326	                        );
327	                    }
328	                }
329	            } else {
330	                completions.extend(
331	                    longs_and_visible_aliases(cmd, disabled)
332	                        .into_iter()
333	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
334	                );
335	                completions.extend(
336	                    hidden_longs_aliases(cmd, disabled)
337	                        .into_iter()
338	                        .filter(|comp| comp.get_value().starts_with(format!("--{flag}").as_str())),
339	                );
340	            }
341	        }
342	    } else if let Some(short) = arg.to_short() {
343	        if !short.is_negative_number() {
344	            // Find the first takes_values option.
345	            let (leading_flags, takes_value_opt, mut short) = parse_shortflags(cmd, short);
346	
347	            // Clone `short` to `peek_short` to peek whether the next flag is a `=`.
348	            if let Some(opt) = takes_value_opt {
349	                if !disabled.contains(opt.get_id()) {
350	                    let mut peek_short = short.clone();
351	                    let has_equal = if let Some(Ok('=')) = peek_short.next_flag() {
352	                        short.next_flag();
353	                        true
354	                    } else {
355	                        false
356	                    };
357	
358	                    let value = short.next_value_os().unwrap_or(OsStr::new(""));
359	                    completions.extend(
360	                        complete_arg_value(value.to_str().ok_or(value), opt, current_dir, 0)
361	                            .into_iter()
362	                            .map(|comp| {
363	                                let sep = if has_equal { "=" } else { "" };
364	                                comp.add_prefix(format!("-{leading_flags}{sep}"))
365	                            }),
366	                    );
367	                }
368	            } else {
369	                completions.extend(
370	                    shorts_and_visible_aliases(cmd, disabled)
371	                        .into_iter()
372	                        .map(|comp| comp.add_prefix(format!("-{leading_flags}"))),
373	                );
374	            }
375	        }
376	    }
377	    debug!("complete_option: completions={completions:?}");
378	    completions
379	}
