381	fn complete_arg_value(
382	    value: Result<&str, &OsStr>,
383	    arg: &clap::Arg,
384	    current_dir: Option<&std::path::Path>,
385	    arg_index: usize,
386	) -> Vec<CompletionCandidate> {
387	    let mut values = Vec::new();
388	    debug!("complete_arg_value: arg={arg:?}, value={value:?}, arg_index={arg_index:?}");
389	
390	    let (prefix, value) =
391	        rsplit_delimiter(value, arg.get_value_delimiter()).unwrap_or((None, value));
392	
393	    let value_os = match value {
394	        Ok(value) => OsStr::new(value),
395	        Err(value_os) => value_os,
396	    };
397	
398	    if let Some(completer) = arg.get::<ArgValueCompleter>() {
399	        values.extend(completer.complete_at(arg_index, value_os));
400	    } else if let Some(completer) = arg.get::<ArgValueCandidates>() {
401	        values.extend(complete_value_candidates(
402	            value_os,
403	            completer.value_candidates(),
404	        ));
405	    } else if let Some(possible_values) = possible_values(arg) {
406	        if let Ok(value) = value {
407	            values.extend(complete_candidates_str(
408	                value,
409	                possible_value_candidates(possible_values),
410	            ));
411	        }
412	    } else {
413	        match arg.get_value_hint() {
414	            clap::ValueHint::Unknown | clap::ValueHint::Other => {
415	                // Should not complete
416	            }
417	            clap::ValueHint::AnyPath => {
418	                values.extend(complete_path(value_os, current_dir, &|_| true));
419	            }
420	            clap::ValueHint::FilePath => {
421	                values.extend(complete_path(value_os, current_dir, &|p| p.is_file()));
422	            }
423	            clap::ValueHint::DirPath => {
424	                values.extend(complete_path(value_os, current_dir, &|p| p.is_dir()));
425	            }
426	            clap::ValueHint::ExecutablePath => {
427	                use is_executable::IsExecutable;
428	                values.extend(complete_path(value_os, current_dir, &|p| p.is_executable()));
429	            }
430	            clap::ValueHint::CommandName
431	            | clap::ValueHint::CommandString
432	            | clap::ValueHint::CommandWithArguments
433	            | clap::ValueHint::Username
434	            | clap::ValueHint::Hostname
435	            | clap::ValueHint::Url
436	            | clap::ValueHint::EmailAddress => {
437	                // No completion implementation
438	            }
439	            _ => {
440	                // Safe-ish fallback
441	                values.extend(complete_path(value_os, current_dir, &|_| true));
442	            }
443	        }
444	
445	        values.sort();
446	    }
447	
448	    if let Some(prefix) = prefix {
449	        values = values
450	            .into_iter()
451	            .map(|comp| comp.add_prefix(prefix))
452	            .collect();
453	    }
454	    values = values
455	        .into_iter()
456	        .map(|comp| {
457	            if comp.get_tag().is_some() {
458	                comp
459	            } else {
460	                comp.tag(Some(arg.to_string().into()))
461	            }
462	        })
463	        .collect();
464	
465	    debug!("complete_arg_value: values={values:?}");
466	    values
467	}
