469	fn rsplit_delimiter<'s, 'o>(
470	    value: Result<&'s str, &'o OsStr>,
471	    delimiter: Option<char>,
472	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
473	    let delimiter = delimiter?;
474	    let value = value.ok()?;
475	    let pos = value.rfind(delimiter)?;
476	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
477	    Some((Some(prefix), Ok(value)))
478	}
