480	fn complete_value_candidates(
481	    value: &OsStr,
482	    completer: &dyn ValueCandidates,
483	) -> Vec<CompletionCandidate> {
484	    debug!("complete_value_candidates: value={value:?}");
485	
486	    let mut values = completer.candidates();
487	    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
488	    values
489	}
