491	fn complete_candidates_str(
492	    value: &str,
493	    mut values: Vec<CompletionCandidate>,
494	) -> Vec<CompletionCandidate> {
495	    debug!("complete_candidates_str: value={value:?}");
496	
497	    values.retain(|comp| comp.get_value().starts_with(value));
498	    values
499	}
