501	fn complete_value_candidates_str(
502	    value: &str,
503	    completer: &dyn ValueCandidates,
504	) -> Vec<CompletionCandidate> {
505	    debug!("complete_value_candidates_str: value={value:?}");
506	
507	    complete_candidates_str(value, completer.candidates())
508	}
