510	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
511	    debug!(
512	        "complete_subcommand: cmd={:?}, value={:?}",
513	        cmd.get_name(),
514	        value
515	    );
516	
517	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
518	        .into_iter()
519	        .filter(|x| x.get_value().starts_with(value))
520	        .collect();
521	    if cmd.is_allow_external_subcommands_set() {
522	        let external_completer = cmd.get::<SubcommandCandidates>();
523	        if let Some(completer) = external_completer {
524	            scs.extend(complete_value_candidates_str(
525	                value,
526	                completer.value_candidates(),
527	            ));
528	        }
529	    }
530	
531	    scs.sort();
532	    scs.dedup();
533	    scs
534	}
