#[test]
fn probe_short_edge_cases() {
    fn command() -> Command {
        Command::new("exhaustive")
            .arg(
                clap::Arg::new("fast")
                    .short('f')
                    .long("fast")
                    .visible_short_alias('q')
                    .visible_alias("quick")
                    .action(clap::ArgAction::SetTrue)
                    .conflicts_with("safe"),
            )
            .arg(
                clap::Arg::new("safe")
                    .short('s')
                    .long("safe")
                    .action(clap::ArgAction::SetTrue),
            )
            .arg(
                clap::Arg::new("tag")
                    .short('t')
                    .long("tag")
                    .value_parser(["alpha", "beta"])
                    .conflicts_with("fast"),
            )
    }

    // Glued value that happens to be a valid flag character: `f` is tag's
    // value, not the fast flag. fast is suppressed by tag, safe stays.
    eprintln!("-tf [TAB]:\n{}", complete!(command(), "-tf [TAB]"));
    // `-t=alpha` glued with equals.
    eprintln!("-t=alpha [TAB]:\n{}", complete!(command(), "-t=alpha [TAB]"));
    // After `-s`, fast's short alias `q` must be hidden too.
    eprintln!("-s -[TAB]:\n{}", complete!(command(), "-s -[TAB]"));
    // Invalid short flag in cluster keeps existing semantics.
    eprintln!("-sx [TAB]:\n{}", complete!(command(), "-sx [TAB]"));
    eprintln!("-xs [TAB]:\n{}", complete!(command(), "-xs [TAB]"));
    // Value-taking member in the middle of a cluster absorbs the rest.
    eprintln!("-fts [TAB]:\n{}", complete!(command(), "-fts [TAB]"));
    // help still available after conflicts
    eprintln!("-f --h[TAB]:\n{}", complete!(command(), "-f --h[TAB]"));

    // Suppressed option's value candidates disappear too.
    let mut cmd = Command::new("exhaustive")
        .arg(
            clap::Arg::new("mode")
                .short('m')
                .long("mode")
                .value_parser(["fast", "slow"])
                .conflicts_with("safe"),
        )
        .arg(
            clap::Arg::new("safe")
                .short('s')
                .long("safe")
                .action(clap::ArgAction::SetTrue),
        );
    eprintln!("-s --mode [TAB]:\n{:?}", complete(&mut cmd, "-s --mode [TAB]", None));
    eprintln!("-s --mode=[TAB]:\n{:?}", complete(&mut cmd, "-s --mode=[TAB]", None));
    eprintln!("-s -m [TAB]:\n{:?}", complete(&mut cmd, "-s -m [TAB]", None));
    eprintln!("-s -m[TAB]:\n{:?}", complete(&mut cmd, "-s -m[TAB]", None));

    // Non-multiple group members recorded via short flags conflict.
    let mut cmd = Command::new("exhaustive")
        .arg(clap::Arg::new("a").short('a').long("a").action(clap::ArgAction::SetTrue))
        .arg(clap::Arg::new("b").short('b').long("b").action(clap::ArgAction::SetTrue))
        .arg(clap::Arg::new("c").short('c').long("c").action(clap::ArgAction::SetTrue))
        .group(clap::ArgGroup::new("ab").args(["a", "b"]).conflicts_with("c"));
    eprintln!("-a [TAB] (group):\n{}", complete(&mut cmd, "-a [TAB]", None));
    eprintln!("-c [TAB] (group):\n{}", complete(&mut cmd, "-c [TAB]", None));

    // Option following a completed short-option value word.
    eprintln!("-t alpha -f [TAB]:\n{}", complete!(command(), "-t alpha -f [TAB]"));
    // After `--`, only positionals; short-flag state still applies.
    let mut cmd = Command::new("exhaustive")
        .arg(clap::Arg::new("positional").value_parser(["pos-a", "pos-b"]))
        .arg(
            clap::Arg::new("fast")
                .short('f')
                .long("fast")
                .action(clap::ArgAction::SetTrue)
                .conflicts_with("safe"),
        )
        .arg(
            clap::Arg::new("safe")
                .short('s')
                .long("safe")
                .action(clap::ArgAction::SetTrue),
        );
    eprintln!("-s -- [TAB]:\n{}", complete(&mut cmd, "-s -- [TAB]", None));
}

